import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import { AlertTriangle, Bell, Building2, CalendarDays, Check, CheckCircle2, ChevronRight, CircleDollarSign, Clock3, Edit2, FileCheck2, FileText, FolderOpen, FolderTree, HardHat, Package, Search, Settings, ShieldAlert, Truck, UserRound, Users, WalletCards, Plus, X, Camera, Trash2, ArrowDownToLine, ArrowUpFromLine, ClipboardList } from "lucide-react";
import { useSyncedAppData } from "@/src/hooks/useSyncedAppData";
import { useProjectBoardData } from "@/src/hooks/useProjectBoardData";
import { apiClient, API_BASE_URL } from "@/src/lib/apiClient";
import { cn } from "@/src/lib/utils";
import { flattenProjects, formatLocalDate } from "@/src/lib/management";
import { getProjectCurrentStageInfo, STAGES } from "./ProjectLifecycle";
import { createEmptyOrganization } from "@/src/lib/workspaceDefaults";

export type MobileWorkspaceModule = "schedule" | "lifecycle" | "files" | "contracts" | "acceptance" | "materials" | "supply" | "cost" | "personnel" | "partners" | "organization" | "settings";

export function MobileWorkspace({ module, setActiveTab, onOpenProject }: { module: MobileWorkspaceModule; setActiveTab: (tab: string) => void; onOpenProject?: (id: string) => void }) {
  switch (module) {
    case "schedule": return <MobileSchedule />;
    case "lifecycle": return <MobileLifecycle onOpenProject={onOpenProject} />;
    case "files": return <MobileFiles setActiveTab={setActiveTab} />;
    case "contracts": return <MobileContracts />;
    case "acceptance": return <MobileAcceptance />;
    case "materials": return <MobileMaterials />;
    case "supply": return <MobileSupply />;
    case "cost": return <MobileCost />;
    case "personnel": return <MobilePersonnel />;
    case "partners": return <MobilePartners />;
    case "organization": return <MobileOrganization />;
    case "settings": return <MobileSettings />;
  }
}

function Page({ eyebrow, title, description, icon: Icon, children }: { eyebrow: string; title: string; description: string; icon: any; children: ReactNode }) {
  return <div className="min-h-full bg-slate-50 px-4 pb-6 pt-4"><header className="rounded-[28px] bg-slate-950 p-5 text-white shadow-lg shadow-slate-900/10"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-medium text-indigo-300">{eyebrow}</p><h2 className="mt-1 text-2xl font-bold tracking-tight">{title}</h2><p className="mt-2 text-sm leading-5 text-slate-400">{description}</p></div><span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-white/10"><Icon className="h-5 w-5" /></span></div></header>{children}</div>;
}

function SearchBox({ value, onChange, placeholder }: { value: string; onChange: (value: string) => void; placeholder: string }) {
  return <div className="mt-4 flex items-center rounded-2xl border border-slate-100 bg-white px-3 py-3 shadow-sm"><Search className="mr-2 h-4 w-4 text-slate-400" /><input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="w-full bg-transparent text-sm text-slate-700 outline-none placeholder:text-slate-400" /></div>;
}

function Metric({ label, value, tone = "text-slate-900" }: { label: string; value: string | number; tone?: string }) {
  return <div className="rounded-2xl border border-slate-100 bg-white p-3 text-center shadow-sm"><p className={cn("text-xl font-bold", tone)}>{value}</p><p className="mt-1 text-[10px] font-medium text-slate-500">{label}</p></div>;
}

function Empty({ text }: { text: string }) { return <div className="rounded-3xl border border-dashed border-slate-200 bg-white px-6 py-12 text-center text-sm text-slate-400">{text}</div>; }

const scheduleSeed = [
  { id: "p1", name: "前期准备阶段", tasks: [{ id: "t1", name: "方案深化与图纸审批", deadline: "2026-07-21", status: "pending", assignee: "陈杰" }, { id: "t2", name: "设备招标及订单下达", deadline: "2026-07-22", status: "in-progress", assignee: "赵敏" }] },
  { id: "p2", name: "项目实施阶段", tasks: [{ id: "t3", name: "电房现场联合检查", deadline: "2026-07-20", status: "pending", assignee: "王强" }, { id: "t4", name: "光伏支架测量复核", deadline: "2026-07-21", status: "completed", assignee: "李娜" }] },
];

function MobileSchedule() {
  const [data, setData] = useSyncedAppData<any[]>("scheduleData", []);
  const [filter, setFilter] = useState<"today" | "overdue" | "all">("today");
  const today = formatLocalDate();
  const tasks = useMemo(() => data.flatMap((project: any) => (project.tasks || []).map((task: any) => ({ ...task, projectId: project.id, projectName: project.name }))), [data]);
  const visible = tasks.filter((task: any) => filter === "all" || (filter === "today" && task.deadline === today) || (filter === "overdue" && task.deadline < today && task.status !== "completed"));
  const completeTask = async (task: any) => setData((current: any[]) => current.map((project: any) => project.id === task.projectId ? { ...project, tasks: project.tasks.map((item: any) => item.id === task.id ? { ...item, status: item.status === "completed" ? "pending" : "completed" } : item) } : project));
  return <Page eyebrow="现场执行" title="待办日程" description="按今天、逾期和全部任务快速处理" icon={CalendarDays}><div className="mt-4 grid grid-cols-3 gap-2"><Metric label="今日" value={tasks.filter((t: any) => t.deadline === today && t.status !== "completed").length} tone="text-indigo-600" /><Metric label="逾期" value={tasks.filter((t: any) => t.deadline < today && t.status !== "completed").length} tone="text-rose-600" /><Metric label="已完成" value={tasks.filter((t: any) => t.status === "completed").length} tone="text-emerald-600" /></div><div className="mt-4 flex gap-2">{[["today", "今天"], ["overdue", "已逾期"], ["all", "全部"]].map(([id, label]) => <button key={id} onClick={() => setFilter(id as any)} className={cn("rounded-full px-4 py-2 text-xs font-semibold", filter === id ? "bg-slate-900 text-white" : "border border-slate-200 bg-white text-slate-500")}>{label}</button>)}</div><div className="mt-4 space-y-3">{visible.map((task: any) => <article key={`${task.projectId}-${task.id}`} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start gap-3"><button onClick={() => void completeTask(task)} className={cn("mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full border", task.status === "completed" ? "border-emerald-500 bg-emerald-500 text-white" : "border-slate-300 text-transparent")}><Check className="h-4 w-4" /></button><div className="min-w-0 flex-1"><h3 className={cn("text-sm font-bold", task.status === "completed" ? "text-slate-400 line-through" : "text-slate-900")}>{task.name}</h3><p className="mt-1 text-xs text-slate-500">{task.projectName} · {task.assignee || "待指派"}</p><span className={cn("mt-3 inline-flex items-center gap-1 rounded-lg px-2 py-1 text-[10px] font-bold", task.deadline < today && task.status !== "completed" ? "bg-rose-50 text-rose-600" : "bg-indigo-50 text-indigo-600")}><Clock3 className="h-3 w-3" />{task.deadline}</span></div></div></article>)}{visible.length === 0 && <Empty text="当前筛选没有待办" />}</div></Page>;
}

function MobileLifecycle({ onOpenProject }: { onOpenProject?: (id: string) => void }) {
  const [board] = useProjectBoardData();
  const [states] = useSyncedAppData<Record<string, any>>("projectLifecycleStates", {});
  const projects = flattenProjects(board);
  return <Page eyebrow="项目推进" title="全生命周期" description="按项目查看当前阶段和资料完成度" icon={FileCheck2}><div className="mt-4 space-y-3">{projects.map((project: any) => { const info = getProjectCurrentStageInfo(project.id, states); return <button key={project.id} onClick={() => onOpenProject?.(project.id)} className="w-full rounded-3xl border border-slate-100 bg-white p-4 text-left shadow-sm"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><h3 className="truncate text-sm font-bold text-slate-900">{project.name}</h3><p className="mt-1 text-xs text-slate-500">负责人：{project.manager || "待指定"}</p></div><ChevronRight className="h-5 w-5 text-slate-300" /></div><div className="mt-4 rounded-2xl bg-indigo-50 p-3"><div className="flex items-center justify-between"><span className="text-xs font-bold text-indigo-700">{info.stage.name}</span><span className="text-xs font-bold text-indigo-600">{info.progressPercent}%</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white"><div className="h-full rounded-full bg-indigo-500" style={{ width: `${info.progressPercent}%` }} /></div><p className="mt-2 text-[10px] text-indigo-500">本阶段需归档 {info.stage.files.length} 类资料</p></div></button>; })}</div></Page>;
}

function MobileFiles({ setActiveTab }: { setActiveTab: (tab: string) => void }) {
  const [board] = useProjectBoardData();
  const [states] = useSyncedAppData<Record<string, any>>("projectLifecycleStates", {});
  const projects = flattenProjects(board);
  const [selectedId, setSelectedId] = useState(projects[0]?.id || "");
  const [files, setFiles] = useState<any>(null);
  const project = projects.find((item: any) => item.id === selectedId) || projects[0];
  useEffect(() => { if (!selectedId && projects[0]?.id) setSelectedId(projects[0].id); }, [projects, selectedId]);
  useEffect(() => { if (!project) return; apiClient.listProjectFiles(project.id, { project, stages: STAGES }).then(setFiles).catch(() => setFiles(null)); }, [project?.id]);
  const total = (files?.stages || []).reduce((sum: number, stage: any) => sum + (stage.files || []).length, 0);
  const info = project ? getProjectCurrentStageInfo(project.id, states) : null;
  return <Page eyebrow="项目归档" title="项目资料" description="按项目和阶段查看现场归档文件" icon={FolderOpen}><select value={selectedId} onChange={(event) => setSelectedId(event.target.value)} className="survey-input mt-4">{projects.map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><div className="mt-3 grid grid-cols-2 gap-3"><Metric label="已归档文件" value={total} tone="text-indigo-600" /><Metric label="开放阶段" value={(info?.index || 0) + 1} tone="text-emerald-600" /></div><div className="mt-4 space-y-3">{(files?.stages || STAGES.slice(0, (info?.index || 0) + 1)).map((stage: any) => <div key={stage.stageId || stage.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600"><FolderOpen className="h-5 w-5" /></span><div><h3 className="text-sm font-bold text-slate-900">{stage.stageName || stage.name}</h3><p className="mt-1 text-xs text-slate-400">{stage.files?.length || 0} 个文件</p></div></div><ChevronRight className="h-5 w-5 text-slate-300" /></div></div>)}</div><button onClick={() => setActiveTab("lifecycle")} className="mt-4 w-full rounded-2xl bg-slate-900 py-3 text-sm font-bold text-white">进入阶段归档</button></Page>;
}

const contractSeed = [{ id: "C-2026-001", name: "A区商业综合体总承包合同", type: "施工合同", partyB: "第一建筑工程公司", amount: "¥12,500万", date: "2026-01-15", status: "active" }, { id: "C-2026-003", name: "B区塔吊租赁合同", type: "租赁合同", partyB: "宏达机械租赁", amount: "¥85万", date: "2026-02-20", status: "pending" }];
function MobileContracts() { const [data] = useSyncedAppData<any[]>("project_contracts", []); const [query, setQuery] = useState(""); const visible = data.filter((item: any) => `${item.name}${item.id}${item.partyB}`.toLowerCase().includes(query.toLowerCase())); return <Page eyebrow="商务管理" title="合同" description="查看合同状态、金额与签约方" icon={FileText}><SearchBox value={query} onChange={setQuery} placeholder="搜索合同或签约方" /><div className="mt-3 grid grid-cols-3 gap-2"><Metric label="合同总数" value={data.length} /><Metric label="执行中" value={data.filter((i: any) => i.status === "active").length} tone="text-emerald-600" /><Metric label="待处理" value={data.filter((i: any) => ["pending", "draft"].includes(i.status)).length} tone="text-amber-600" /></div><div className="mt-4 space-y-3">{visible.map((item: any) => <article key={item.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><span className="rounded-lg bg-indigo-50 px-2 py-1 text-[10px] font-bold text-indigo-600">{item.type}</span><span className={cn("rounded-lg px-2 py-1 text-[10px] font-bold", item.status === "active" ? "bg-emerald-50 text-emerald-600" : "bg-amber-50 text-amber-600")}>{item.status === "active" ? "执行中" : "待处理"}</span></div><h3 className="mt-3 text-sm font-bold text-slate-900">{item.name}</h3><p className="mt-2 text-xs text-slate-500">{item.partyB || "未填写签约方"}</p><div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3"><span className="text-xs text-slate-400">{item.id} · {item.date}</span><span className="text-sm font-bold text-slate-900">{item.amount}</span></div></article>)}</div></Page>; }

const acceptanceStatusMap: Record<string, [string, string]> = { passed: ["验收通过", "bg-emerald-50 text-emerald-600"], recheck_passed: ["复验通过", "bg-indigo-50 text-indigo-600"], rework_required: ["需返工", "bg-rose-50 text-rose-600"], rework_in_progress: ["返工中", "bg-amber-50 text-amber-600"], pending: ["待验收", "bg-slate-100 text-slate-500"] };
function MobileAcceptance() {
  const [records, setRecords] = useSyncedAppData<any[]>("projectAcceptanceRecords", []);
  const [board] = useProjectBoardData();
  const projects = flattenProjects(board);
  const [sheet, setSheet] = useState(false);
  const photoRef = useRef<HTMLInputElement>(null);
  const [form, setForm] = useState({ projectName: projects[0]?.name || "", title: "", inspector: "", acceptedAt: new Date().toISOString().slice(0, 16), result: "pass", notes: "", photos: [] as string[], reworkItems: [] as any[] });
  const uploadPhotos = async (files: FileList | null) => {
    if (!files?.length) return;
    const selected = Array.from(files).slice(0, 6 - form.photos.length);
    const urls = await Promise.all(selected.map(async file => {
      const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || "")); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); });
      const uploaded = await apiClient.uploadFile(file.name, dataUrl.split(",")[1] || "");
      return `${API_BASE_URL}${uploaded.url}`;
    }));
    setForm(current => ({ ...current, photos: [...current.photos, ...urls].slice(0, 6) }));
  };
  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!form.projectName || !form.title.trim() || !form.inspector.trim() || form.photos.length === 0) { window.dispatchEvent(new CustomEvent("show-toast", { detail: "请完整填写验收信息并上传照片" })); return; }
    if (form.result === "rework" && form.reworkItems.some(item => !item.issue.trim() || !item.owner.trim() || !item.deadline)) { window.dispatchEvent(new CustomEvent("show-toast", { detail: "请完整填写返工项" })); return; }
    const project = projects.find((item: any) => item.name === form.projectName);
    const record = { id: `AC-${Date.now()}`, projectId: project?.id || "", projectName: form.projectName, title: form.title.trim(), acceptanceType: "现场验收", inspector: form.inspector.trim(), acceptedAt: form.acceptedAt, createdAt: new Date().toISOString(), status: form.result === "pass" ? "passed" : "rework_required", result: form.result, notes: form.notes.trim(), photos: form.photos, reworkItems: form.result === "rework" ? form.reworkItems.map(item => ({ ...item, id: item.id || `rw-${Date.now()}`, status: "open", createdAt: new Date().toISOString(), photos: [] })) : [] };
    setRecords(current => [record, ...current]);
    setForm({ projectName: projects[0]?.name || "", title: "", inspector: "", acceptedAt: new Date().toISOString().slice(0, 16), result: "pass", notes: "", photos: [], reworkItems: [] });
    setSheet(false);
    window.dispatchEvent(new CustomEvent("show-toast", { detail: "验收记录已保存" }));
  };
  const completeRework = (recordId: string, reworkId: string) => setRecords(current => current.map(record => record.id === recordId ? { ...record, status: "rework_in_progress", reworkItems: record.reworkItems.map((item: any) => item.id === reworkId ? { ...item, status: "done", completedAt: new Date().toISOString(), completionNote: "手机端标记完成" } : item) } : record));
  const passRecheck = (record: any) => { if ((record.reworkItems || []).some((item: any) => item.status !== "done")) { window.dispatchEvent(new CustomEvent("show-toast", { detail: "返工项完成后才能复验通过" })); return; } setRecords(current => current.map(item => item.id === record.id ? { ...item, status: "recheck_passed", recheckedAt: new Date().toISOString() } : item)); };
  return <Page eyebrow="质量闭环" title="项目验收" description="记录验收时间戳、照片凭证和返工闭环" icon={FileCheck2}><div className="mt-4 grid grid-cols-3 gap-2"><Metric label="全部" value={records.length} /><Metric label="通过" value={records.filter(i => ["passed", "recheck_passed"].includes(i.status)).length} tone="text-emerald-600" /><Metric label="返工" value={records.filter(i => ["rework_required", "rework_in_progress"].includes(i.status)).length} tone="text-rose-600" /></div><button onClick={() => setSheet(true)} className="mt-4 w-full rounded-2xl bg-indigo-600 py-3.5 text-sm font-bold text-white">新增验收记录</button><div className="mt-4 space-y-3">{records.map(record => { const status = acceptanceStatusMap[record.status] || acceptanceStatusMap.pending; return <article key={record.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><h3 className="text-sm font-bold text-slate-900">{record.title}</h3><p className="mt-1 text-xs text-slate-500">{record.projectName} · {record.inspector}</p><p className="mt-1 text-[10px] text-slate-400">{String(record.acceptedAt || "").replace("T", " ")}</p></div><span className={cn("rounded-lg px-2 py-1 text-[10px] font-bold", status[1])}>{status[0]}</span></div>{record.photos?.length > 0 && <div className="mt-3 flex gap-2">{record.photos.slice(0, 4).map((photo: string) => <img key={photo} src={photo} alt="验收照片" className="h-12 w-12 rounded-xl object-cover" />)}</div>}{record.reworkItems?.length > 0 && <div className="mt-3 space-y-2">{record.reworkItems.map((item: any) => <div key={item.id} className="rounded-2xl bg-amber-50 p-3 text-xs text-amber-800"><p className="font-bold">{item.issue}</p><p className="mt-1">责任人：{item.owner} · 期限：{item.deadline}</p>{item.status !== "done" && <button onClick={() => completeRework(record.id, item.id)} className="mt-2 rounded-lg bg-emerald-600 px-2 py-1 text-[10px] font-bold text-white">标记完成</button>}</div>)}{record.reworkItems.every((item: any) => item.status === "done") && record.status !== "recheck_passed" && <button onClick={() => passRecheck(record)} className="w-full rounded-xl bg-slate-900 py-2 text-xs font-bold text-white">复验通过</button>}</div>}</article>; })}{records.length === 0 && <Empty text="暂无验收记录" />}</div>{sheet && <div className="fixed inset-0 z-[80] flex items-end bg-slate-950/50"><form onSubmit={submit} className="max-h-[92vh] w-full overflow-y-auto rounded-t-[32px] bg-slate-50 p-5"><div className="mb-5 flex items-center justify-between"><h3 className="text-lg font-bold text-slate-900">新增验收</h3><button type="button" onClick={() => setSheet(false)} className="rounded-full bg-white p-2 text-slate-500"><X className="h-5 w-5" /></button></div><div className="space-y-4"><select value={form.projectName} onChange={event => setForm({ ...form, projectName: event.target.value })} className="survey-input">{projects.map((project: any) => <option key={project.id}>{project.name}</option>)}</select><input value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} className="survey-input" placeholder="验收标题" required /><input value={form.inspector} onChange={event => setForm({ ...form, inspector: event.target.value })} className="survey-input" placeholder="验收人" required /><input type="datetime-local" value={form.acceptedAt} onChange={event => setForm({ ...form, acceptedAt: event.target.value })} className="survey-input" required /><select value={form.result} onChange={event => setForm({ ...form, result: event.target.value, reworkItems: event.target.value === "rework" && form.reworkItems.length === 0 ? [{ id: `rw-${Date.now()}`, issue: "", owner: "", deadline: "" }] : form.reworkItems })} className="survey-input"><option value="pass">验收通过</option><option value="rework">需返工</option></select>{form.result === "rework" && <div className="space-y-3">{form.reworkItems.map((item, index) => <div key={item.id} className="rounded-2xl bg-amber-50 p-3"><input value={item.issue} onChange={event => setForm({ ...form, reworkItems: form.reworkItems.map(current => current.id === item.id ? { ...current, issue: event.target.value } : current) })} className="survey-input" placeholder={`返工问题 ${index + 1}`} /><input value={item.owner} onChange={event => setForm({ ...form, reworkItems: form.reworkItems.map(current => current.id === item.id ? { ...current, owner: event.target.value } : current) })} className="survey-input mt-2" placeholder="责任人" /><input type="date" value={item.deadline} onChange={event => setForm({ ...form, reworkItems: form.reworkItems.map(current => current.id === item.id ? { ...current, deadline: event.target.value } : current) })} className="survey-input mt-2" /></div>)}<button type="button" onClick={() => setForm({ ...form, reworkItems: [...form.reworkItems, { id: `rw-${Date.now()}`, issue: "", owner: "", deadline: "" }] })} className="w-full rounded-2xl border border-amber-200 py-3 text-sm font-bold text-amber-700">添加返工项</button></div>}<textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} className="survey-input" rows={2} placeholder="验收备注" /><div><div className="mb-2 text-xs font-bold text-slate-600">验收照片 *</div><div className="flex flex-wrap gap-2">{form.photos.map(photo => <img key={photo} src={photo} alt="验收照片" className="h-16 w-16 rounded-xl object-cover" />)}<button type="button" onClick={() => photoRef.current?.click()} className="flex h-16 w-16 items-center justify-center rounded-xl border-2 border-dashed border-slate-300 text-slate-400"><Camera className="h-5 w-5" /></button><input ref={photoRef} type="file" accept="image/*" capture="environment" multiple className="hidden" onChange={event => { void uploadPhotos(event.target.files); event.target.value = ""; }} /></div></div><button type="submit" className="w-full rounded-2xl bg-indigo-600 py-3.5 text-sm font-bold text-white">保存验收记录</button></div></form></div>}</Page>;
}

const materialSeed = [{ id: "M-001", name: "单晶硅光伏组件", spec: "550Wp", stock: 1200, unit: "块", location: "A区露天堆场", status: "sufficient", project: "A区商业综合体" }, { id: "M-002", name: "磷酸铁锂电池簇", spec: "280Ah/1P52S", stock: 4, unit: "套", location: "B区恒温库", status: "warning", project: "B区住宅一期" }, { id: "M-004", name: "交联聚乙烯电缆", spec: "YJV22-8.7/15kV", stock: 150, unit: "米", location: "C区线缆库", status: "critical", project: "C区地下车库" }];
function MobileMaterials() {
  const [data, setData] = useSyncedAppData<any[]>("materialsData", []);
  const [transactions, setTransactions] = useSyncedAppData<any[]>("warehouseTransactions", []);
  const [outboundOrders, setOutboundOrders] = useSyncedAppData<any[]>("warehouseOutboundOrders", []);
  const [board] = useProjectBoardData();
  const projectNames = useMemo(() => flattenProjects(board).map((project: any) => project.name), [board]);
  const [query, setQuery] = useState("");
  const [alerts, setAlerts] = useState(false);
  const [view, setView] = useState<"stock" | "records">("stock");
  const [sheet, setSheet] = useState<"inbound" | "outbound" | null>(null);
  const inboundPhotoRef = useRef<HTMLInputElement>(null);
  const outboundPhotoRef = useRef<HTMLInputElement>(null);
  const nowValue = () => new Date().toISOString().slice(0, 16);
  const blankInbound = () => ({ sourceType: "project", sourceProject: "", name: "", spec: "", quantity: "", unit: "", location: "", supplier: "", type: "", occurredAt: nowValue(), photos: [] as string[], remark: "" });
  const blankOutbound = () => ({ materialId: "", quantity: "", destinationProject: "", receiver: "", occurredAt: nowValue(), photos: [] as string[], remark: "" });
  const [inbound, setInbound] = useState(blankInbound);
  const [outbound, setOutbound] = useState(blankOutbound);
  const visible = data.filter((item: any) => (!alerts || item.status !== "sufficient") && `${item.name}${item.id}${item.spec}${item.sourceProject || item.project}`.toLowerCase().includes(query.toLowerCase()));
  const inputClass = "w-full rounded-2xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-700 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/10";

  const uploadPhotos = async (files: FileList | null, direction: "inbound" | "outbound") => {
    if (!files?.length) return;
    const existing = direction === "inbound" ? inbound.photos : outbound.photos;
    const selected = Array.from(files).slice(0, 3 - existing.length);
    if (selected.some(file => file.size > 5 * 1024 * 1024)) {
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "单张照片不能超过 5MB" }));
      return;
    }
    try {
      const urls = await Promise.all(selected.map(async file => {
        const dataUrl = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(String(reader.result || ""));
          reader.onerror = () => reject(reader.error);
          reader.readAsDataURL(file);
        });
        const result = await apiClient.uploadFile(file.name, dataUrl.split(",")[1] || "");
        return `${API_BASE_URL}${result.url}`;
      }));
      if (direction === "inbound") setInbound(current => ({ ...current, photos: [...current.photos, ...urls].slice(0, 3) }));
      else setOutbound(current => ({ ...current, photos: [...current.photos, ...urls].slice(0, 3) }));
      window.dispatchEvent(new CustomEvent("show-toast", { detail: `已上传 ${urls.length} 张照片` }));
    } catch {
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "照片上传失败，请检查网络后重试" }));
    }
  };

  const submitInbound = (event: FormEvent) => {
    event.preventDefault();
    const quantity = Number(inbound.quantity);
    if (!inbound.sourceProject.trim() || !inbound.name.trim() || !inbound.spec.trim() || quantity <= 0 || !inbound.unit.trim() || !inbound.location.trim()) {
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "请完整填写入库必填信息" }));
      return;
    }
    const existing = data.find((item: any) => item.name.trim() === inbound.name.trim() && item.spec.trim() === inbound.spec.trim() && item.location.trim() === inbound.location.trim());
    const materialId = existing?.id || `M-${Date.now().toString().slice(-8)}`;
    setData((current: any[]) => existing ? current.map((item: any) => item.id === existing.id ? { ...item, stock: Number(item.stock) + quantity, status: "sufficient", sourceType: inbound.sourceType, sourceProject: inbound.sourceProject.trim(), project: inbound.sourceProject.trim(), supplier: inbound.supplier.trim() || item.supplier, type: inbound.type || item.type, inboundAt: inbound.occurredAt, photos: inbound.photos.length ? inbound.photos : item.photos } : item) : [{ id: materialId, name: inbound.name.trim(), spec: inbound.spec.trim(), stock: quantity, unit: inbound.unit.trim(), location: inbound.location.trim(), status: "sufficient", sourceType: inbound.sourceType, sourceProject: inbound.sourceProject.trim(), project: inbound.sourceProject.trim(), supplier: inbound.supplier.trim() || "未填写", type: inbound.type || "未分类", inboundAt: inbound.occurredAt, photos: inbound.photos }, ...current]);
    setTransactions((current: any[]) => [{ id: `WIN-${Date.now()}`, direction: "inbound", materialId, materialName: inbound.name.trim(), spec: inbound.spec.trim(), quantity, unit: inbound.unit.trim(), occurredAt: inbound.occurredAt, sourceType: inbound.sourceType, sourceProject: inbound.sourceProject.trim(), location: inbound.location.trim(), supplier: inbound.supplier.trim(), photos: inbound.photos, remark: inbound.remark.trim() }, ...current]);
    setInbound(blankInbound());
    setSheet(null);
    window.dispatchEvent(new CustomEvent("show-toast", { detail: inbound.sourceType === "purchase" ? "新采购材料已入库并同步" : "材料已入库并同步" }));
  };

  const submitOutbound = (event: FormEvent) => {
    event.preventDefault();
    const material = data.find((item: any) => item.id === outbound.materialId);
    const quantity = Number(outbound.quantity);
    if (!material || quantity <= 0 || !outbound.destinationProject.trim() || !outbound.receiver.trim()) {
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "请完整填写出库必填信息" }));
      return;
    }
    if (outbound.photos.length === 0) {
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "出库单必须上传至少 1 张照片" }));
      return;
    }
    const orderNo = `CK-${new Date().toISOString().slice(0, 10).replace(/-/g, "")}-${String(outboundOrders.length + 1).padStart(4, "0")}`;
    setOutboundOrders((current: any[]) => [{ id: `WO-${Date.now()}`, orderNo, createdBy: "mobile", createdByName: "手机端用户", createdAt: new Date().toISOString(), submittedAt: outbound.occurredAt, status: "pending", destinationProject: outbound.destinationProject.trim(), receiver: outbound.receiver.trim(), remark: outbound.remark.trim(), photos: outbound.photos, items: [{ id: `line-${Date.now()}`, materialId: material.id, materialName: material.name, spec: material.spec, batch: material.inboundAt || material.id, location: material.location, quantity, unit: material.unit, stockAtSubmit: Number(material.stock || 0) }] }, ...current]);
    setOutbound(blankOutbound());
    setSheet(null);
    window.dispatchEvent(new CustomEvent("show-toast", { detail: quantity > Number(material.stock) ? "出库单已提交审核，库存不足请关注" : "出库单已提交审核" }));
  };

  const PhotoPicker = ({ direction, photos }: { direction: "inbound" | "outbound"; photos: string[] }) => {
    const inputRef = direction === "inbound" ? inboundPhotoRef : outboundPhotoRef;
    const remove = (index: number) => direction === "inbound" ? setInbound(current => ({ ...current, photos: current.photos.filter((_, i) => i !== index) })) : setOutbound(current => ({ ...current, photos: current.photos.filter((_, i) => i !== index) }));
    return <div><div className="mb-2 flex items-center justify-between"><label className="text-xs font-bold text-slate-600">现场照片</label><span className="text-[10px] text-slate-400">最多3张</span></div><div className="flex flex-wrap gap-2">{photos.map((photo, index) => <div key={photo} className="relative h-20 w-20 overflow-hidden rounded-2xl border border-slate-200"><img src={photo} alt="材料凭证" className="h-full w-full object-cover" /><button type="button" onClick={() => remove(index)} className="absolute right-1 top-1 rounded-full bg-slate-900/70 p-1 text-white"><Trash2 className="h-3 w-3" /></button></div>)}{photos.length < 3 && <button type="button" onClick={() => inputRef.current?.click()} className="flex h-20 w-20 flex-col items-center justify-center rounded-2xl border-2 border-dashed border-slate-300 text-slate-400"><Camera className="h-5 w-5" /><span className="mt-1 text-[10px]">拍照/上传</span></button>}<input ref={inputRef} type="file" accept="image/*" capture="environment" multiple className="hidden" onChange={(event) => { void uploadPhotos(event.target.files, direction); event.target.value = ""; }} /></div></div>;
  };

  return <Page eyebrow="现场物资" title="材料库存" description="电脑与手机共用库存、出入库记录和照片凭证" icon={Package}>
    <div className="mt-4 grid grid-cols-2 gap-2">
      <button onClick={() => setView("stock")} className={cn("rounded-2xl py-3 text-xs font-bold", view === "stock" ? "bg-slate-900 text-white" : "border border-slate-200 bg-white text-slate-500")}>库存管理</button>
      <button onClick={() => setView("records")} className={cn("rounded-2xl py-3 text-xs font-bold", view === "records" ? "bg-slate-900 text-white" : "border border-slate-200 bg-white text-slate-500")}>流转/出库单 ({transactions.length + outboundOrders.length})</button>
    </div>
    {view === "stock" ? <>
      <div className="mt-3 grid grid-cols-2 gap-2"><button onClick={() => setSheet("inbound")} className="flex items-center justify-center rounded-2xl bg-indigo-600 py-3 text-sm font-bold text-white shadow-sm"><ArrowDownToLine className="mr-2 h-4 w-4" />入库/新采购</button><button onClick={() => setSheet("outbound")} className="flex items-center justify-center rounded-2xl border border-slate-200 bg-white py-3 text-sm font-bold text-slate-700"><ArrowUpFromLine className="mr-2 h-4 w-4" />出库登记</button></div>
      <SearchBox value={query} onChange={setQuery} placeholder="搜索材料、编号、规格或来源项目" />
      <div className="mt-3 grid grid-cols-3 gap-2"><Metric label="物资种类" value={data.length} /><Metric label="库存预警" value={data.filter((i: any) => i.status === "warning").length} tone="text-amber-600" /><Metric label="缺货" value={data.filter((i: any) => i.status === "critical").length} tone="text-rose-600" /></div>
      <button onClick={() => setAlerts(!alerts)} className={cn("mt-4 rounded-full px-4 py-2 text-xs font-semibold", alerts ? "bg-rose-600 text-white" : "border border-slate-200 bg-white text-slate-500")}>只看库存异常</button>
      <div className="mt-4 space-y-3">{visible.map((item: any) => <article key={item.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="text-[10px] font-bold text-slate-400">{item.id}</p><h3 className="mt-1 truncate text-sm font-bold text-slate-900">{item.name}</h3><p className="mt-1 text-xs text-slate-500">{item.spec}</p><p className="mt-1 truncate text-[10px] text-indigo-500">{item.sourceType === "purchase" ? "新采购" : "来源"}：{item.sourceProject || item.project || "未登记"}</p></div><span className={cn("rounded-lg px-2 py-1 text-[10px] font-bold", item.status === "critical" ? "bg-rose-50 text-rose-600" : item.status === "warning" ? "bg-amber-50 text-amber-600" : "bg-emerald-50 text-emerald-600")}>{item.status === "critical" ? "缺货" : item.status === "warning" ? "预警" : "充足"}</span></div><div className="mt-4 flex items-end justify-between rounded-2xl bg-slate-50 p-3"><div><p className="text-[10px] text-slate-400">当前库存</p><p className="mt-1 text-xl font-bold text-slate-900">{item.stock} <span className="text-xs font-normal text-slate-500">{item.unit}</span></p></div><p className="text-xs text-slate-500">{item.location}</p></div></article>)}{visible.length === 0 && <Empty text="暂无匹配的库存材料" />}</div>
    </> : <div className="mt-4 space-y-3">{outboundOrders.map((order: any) => <article key={order.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><span className={cn("inline-flex items-center rounded-lg px-2 py-1 text-[10px] font-bold", order.status === "approved" ? "bg-emerald-50 text-emerald-600" : order.status === "cancelled" ? "bg-rose-50 text-rose-600" : "bg-amber-50 text-amber-600")}>出库单 · {order.status === "approved" ? "已通过" : order.status === "cancelled" ? "已撤销" : "待审核"}</span><span className="text-[10px] text-slate-400">{String(order.submittedAt || "").replace("T", " ")}</span></div><h3 className="mt-3 text-sm font-bold text-slate-900">{order.orderNo}</h3><p className="mt-1 text-xs text-slate-500">{order.items?.map((item: any) => `${item.materialName} ${item.quantity}${item.unit}`).join("、")}</p><div className="mt-3 rounded-2xl bg-slate-50 p-3"><p className="text-[10px] text-slate-400">去向</p><p className="mt-1 text-xs font-medium text-slate-700">{order.destinationProject} · {order.receiver}</p></div></article>)}{transactions.map((record: any) => <article key={record.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><span className={cn("inline-flex items-center rounded-lg px-2 py-1 text-[10px] font-bold", record.direction === "inbound" ? "bg-emerald-50 text-emerald-600" : "bg-indigo-50 text-indigo-600")}>{record.direction === "inbound" ? <ArrowDownToLine className="mr-1 h-3 w-3" /> : <ArrowUpFromLine className="mr-1 h-3 w-3" />}{record.direction === "inbound" ? "入库" : "出库流水"}</span><span className="text-[10px] text-slate-400">{String(record.occurredAt || "").replace("T", " ")}</span></div><h3 className="mt-3 text-sm font-bold text-slate-900">{record.materialName}</h3><p className="mt-1 text-xs text-slate-500">{record.spec} · {record.direction === "inbound" ? "+" : "-"}{record.quantity} {record.unit}</p><div className="mt-3 rounded-2xl bg-slate-50 p-3"><p className="text-[10px] text-slate-400">{record.direction === "inbound" ? "来源" : "去向"}</p><p className="mt-1 text-xs font-medium text-slate-700">{record.direction === "inbound" ? record.sourceProject : record.destinationProject}</p></div>{record.photos?.length > 0 && <div className="mt-3 flex gap-2">{record.photos.map((photo: string) => <a key={photo} href={photo} target="_blank" rel="noreferrer"><img src={photo} alt="流转凭证" className="h-12 w-12 rounded-xl object-cover" /></a>)}</div>}</article>)}{transactions.length + outboundOrders.length === 0 && <Empty text="暂无出入库流转记录" />}</div>}

    {sheet === "inbound" && <div className="fixed inset-0 z-[80] flex items-end bg-slate-950/50"><div className="max-h-[92vh] w-full overflow-y-auto rounded-t-[32px] bg-slate-50 p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="text-lg font-bold text-slate-900">入库登记</h3><p className="mt-1 text-xs text-slate-500">支持未登记项目和新采购材料</p></div><button onClick={() => setSheet(null)} className="rounded-full bg-white p-2 text-slate-500"><X className="h-5 w-5" /></button></div><form onSubmit={submitInbound} className="space-y-4"><div><label className="mb-1.5 block text-xs font-bold text-slate-600">来源类型 *</label><select value={inbound.sourceType} onChange={(event) => setInbound({ ...inbound, sourceType: event.target.value, sourceProject: "" })} className={inputClass}><option value="project">项目调拨</option><option value="purchase">新采购材料</option><option value="other">其他来源</option></select></div><div><label className="mb-1.5 block text-xs font-bold text-slate-600">{inbound.sourceType === "project" ? "来源项目" : inbound.sourceType === "purchase" ? "采购批次/来源" : "来源说明"} *</label><input list={inbound.sourceType === "project" ? "mobile-source-projects" : undefined} value={inbound.sourceProject} onChange={(event) => setInbound({ ...inbound, sourceProject: event.target.value })} className={inputClass} placeholder={inbound.sourceType === "project" ? "选择或输入未登记项目" : "直接输入来源信息"} required /><datalist id="mobile-source-projects">{projectNames.map(name => <option key={name} value={name} />)}</datalist>{inbound.sourceType === "project" && <p className="mt-1 text-[10px] text-slate-400">项目未登记也可以直接输入名称</p>}</div><div className="grid grid-cols-2 gap-3"><div><label className="mb-1.5 block text-xs font-bold text-slate-600">材料名称 *</label><input value={inbound.name} onChange={(event) => setInbound({ ...inbound, name: event.target.value })} className={inputClass} placeholder="新材料可直接填写" required /></div><div><label className="mb-1.5 block text-xs font-bold text-slate-600">规格型号 *</label><input value={inbound.spec} onChange={(event) => setInbound({ ...inbound, spec: event.target.value })} className={inputClass} placeholder="规格/型号" required /></div></div><div className="grid grid-cols-2 gap-3"><div><label className="mb-1.5 block text-xs font-bold text-slate-600">数量 *</label><input type="number" min="0.0001" step="any" value={inbound.quantity} onChange={(event) => setInbound({ ...inbound, quantity: event.target.value })} className={inputClass} required /></div><div><label className="mb-1.5 block text-xs font-bold text-slate-600">单位 *</label><input value={inbound.unit} onChange={(event) => setInbound({ ...inbound, unit: event.target.value })} className={inputClass} placeholder="个/米/吨" required /></div></div><div className="grid grid-cols-2 gap-3"><div><label className="mb-1.5 block text-xs font-bold text-slate-600">存放区域 *</label><input value={inbound.location} onChange={(event) => setInbound({ ...inbound, location: event.target.value })} className={inputClass} required /></div><div><label className="mb-1.5 block text-xs font-bold text-slate-600">入库时间 *</label><input type="datetime-local" value={inbound.occurredAt} onChange={(event) => setInbound({ ...inbound, occurredAt: event.target.value })} className={inputClass} required /></div></div><div><label className="mb-1.5 block text-xs font-bold text-slate-600">供应商/承运方</label><input value={inbound.supplier} onChange={(event) => setInbound({ ...inbound, supplier: event.target.value })} className={inputClass} placeholder="新采购时建议填写" /></div><PhotoPicker direction="inbound" photos={inbound.photos} /><textarea value={inbound.remark} onChange={(event) => setInbound({ ...inbound, remark: event.target.value })} className={inputClass} rows={2} placeholder="备注、车牌号或验收情况" /><button type="submit" className="w-full rounded-2xl bg-indigo-600 py-3.5 text-sm font-bold text-white">确认入库并同步</button></form></div></div>}

    {sheet === "outbound" && <div className="fixed inset-0 z-[80] flex items-end bg-slate-950/50"><div className="max-h-[92vh] w-full overflow-y-auto rounded-t-[32px] bg-slate-50 p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="text-lg font-bold text-slate-900">创建出库单</h3><p className="mt-1 text-xs text-slate-500">手机端提交后进入待审核，不直接扣库存</p></div><button onClick={() => setSheet(null)} className="rounded-full bg-white p-2 text-slate-500"><X className="h-5 w-5" /></button></div><form onSubmit={submitOutbound} className="space-y-4"><div><label className="mb-1.5 block text-xs font-bold text-slate-600">在库材料 *</label><select value={outbound.materialId} onChange={(event) => setOutbound({ ...outbound, materialId: event.target.value, quantity: "" })} className={inputClass} required><option value="">请选择材料</option>{data.map((item: any) => <option key={item.id} value={item.id}>{item.name}｜{item.spec}｜{item.stock}{item.unit}</option>)}</select></div><div className="grid grid-cols-2 gap-3"><div><label className="mb-1.5 block text-xs font-bold text-slate-600">出库数量 *</label><input type="number" min="0.0001" step="any" value={outbound.quantity} onChange={(event) => setOutbound({ ...outbound, quantity: event.target.value })} className={inputClass} required /></div><div><label className="mb-1.5 block text-xs font-bold text-slate-600">出库时间 *</label><input type="datetime-local" value={outbound.occurredAt} onChange={(event) => setOutbound({ ...outbound, occurredAt: event.target.value })} className={inputClass} required /></div></div>{(() => { const material = data.find((item: any) => item.id === outbound.materialId); const shortage = material && Number(outbound.quantity) > Number(material.stock); return shortage ? <p className="rounded-2xl bg-amber-50 p-3 text-xs font-medium text-amber-700">库存不足：当前库存 {material.stock}{material.unit}，仍可提交审核。</p> : null; })()}<div><label className="mb-1.5 block text-xs font-bold text-slate-600">去向项目 *</label><input list="mobile-destination-projects" value={outbound.destinationProject} onChange={(event) => setOutbound({ ...outbound, destinationProject: event.target.value })} className={inputClass} placeholder="选择或输入未登记项目" required /><datalist id="mobile-destination-projects">{projectNames.map(name => <option key={name} value={name} />)}</datalist></div><div><label className="mb-1.5 block text-xs font-bold text-slate-600">接收人 *</label><input value={outbound.receiver} onChange={(event) => setOutbound({ ...outbound, receiver: event.target.value })} className={inputClass} placeholder="项目现场接收人" required /></div><PhotoPicker direction="outbound" photos={outbound.photos} /><textarea value={outbound.remark} onChange={(event) => setOutbound({ ...outbound, remark: event.target.value })} className={inputClass} rows={2} placeholder="领用人、车牌号或交接情况" /><button type="submit" className="w-full rounded-2xl bg-slate-900 py-3.5 text-sm font-bold text-white">提交审核</button></form></div></div>}
  </Page>;
}

const supplySeed = [{ id: "PO-2026-001", supplier: "隆基绿能科技", items: "单晶硅光伏组件 550Wp", amount: "¥1,250,000", expectedDate: "2026-03-20", status: "in-transit" }, { id: "PO-2026-002", supplier: "宁德时代新能源", items: "储能电池预制舱 2MWh", amount: "¥3,800,000", expectedDate: "2026-03-15", status: "delayed" }, { id: "PO-2026-003", supplier: "华为技术", items: "智能组串式逆变器", amount: "¥450,000", expectedDate: "2026-03-10", status: "delivered" }];
const supplyStatus: Record<string, [string, string]> = { "in-transit": ["运输中", "bg-blue-50 text-blue-600"], delayed: ["已延期", "bg-rose-50 text-rose-600"], delivered: ["已交付", "bg-emerald-50 text-emerald-600"], production: ["生产中", "bg-amber-50 text-amber-600"] };
