function MobileCost() { const [data] = useSyncedAppData<any[]>("costDataV2", []); const totals = data.reduce((sum: any, item: any) => { const budget = Object.values(item.budget || {}).reduce<number>((a, b) => a + Number(b || 0), 0); const actual = (item.actualLedger || []).reduce((a: number, b: any) => a + Number(b.amount || 0), 0); const received = (item.collection?.records || []).filter((r: any) => r.status === "received").reduce((a: number, b: any) => a + Number(b.amount || 0), 0); return { budget: sum.budget + budget, actual: sum.actual + actual, received: sum.received + received }; }, { budget: 0, actual: 0, received: 0 }); return <Page eyebrow="经营管理" title="成本与预算" description="手机端查看预算占用、支出和回款" icon={CircleDollarSign}><div className="mt-4 grid grid-cols-3 gap-2"><Metric label="总预算(万)" value={totals.budget.toLocaleString()} /><Metric label="已支出(万)" value={totals.actual.toLocaleString()} tone="text-rose-600" /><Metric label="已回款(万)" value={totals.received.toLocaleString()} tone="text-emerald-600" /></div><div className="mt-4 space-y-3">{data.map((item: any) => { const budget = Object.values(item.budget || {}).reduce<number>((a, b) => a + Number(b || 0), 0); const actual = (item.actualLedger || []).reduce((a: number, b: any) => a + Number(b.amount || 0), 0); const usage = budget ? Math.round(actual / budget * 100) : 0; return <article key={item.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><h3 className="text-sm font-bold text-slate-900">{item.project}</h3><span className="text-sm font-bold text-indigo-600">{usage}%</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-indigo-500" style={{ width: `${Math.min(100, usage)}%` }} /></div><div className="mt-4 grid grid-cols-2 gap-2"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] text-slate-400">预算</p><p className="mt-1 text-sm font-bold text-slate-800">¥{budget.toLocaleString()}万</p></div><div className="rounded-xl bg-rose-50 p-3"><p className="text-[10px] text-rose-400">支出</p><p className="mt-1 text-sm font-bold text-rose-700">¥{actual.toLocaleString()}万</p></div></div></article>; })}</div></Page>; }

const personnelSeed = [{ id: "W001", name: "张伟", role: "项目经理", team: "管理组", status: "on-site", safetyTrained: true, projects: [{ name: "A区商业综合体", status: "active" }] }, { id: "W002", name: "李娜", role: "安全员", team: "管理组", status: "on-site", safetyTrained: true, projects: [{ name: "A区商业综合体", status: "active" }] }, { id: "W005", name: "陈杰", role: "焊工", team: "安装二班", status: "on-site", safetyTrained: false, projects: [{ name: "B区住宅一期", status: "active" }] }];
function MobilePersonnel() {
  const [data, setData] = useSyncedAppData<any[]>("personnelData", []);
  const [query, setQuery] = useState("");
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const visible = data.filter((item: any) => `${item.name}${item.role}${item.team}`.toLowerCase().includes(query.toLowerCase()));
  const deleteTarget = data.find((item: any) => item.id === deleteId);
  const confirmDelete = () => {
    if (!deleteId) return;
    void setData((current: any[]) => current.filter((item: any) => item.id !== deleteId));
    window.dispatchEvent(new CustomEvent("show-toast", { detail: `${deleteTarget?.name || "人员"}已删除` }));
    setDeleteId(null);
  };
  return <Page eyebrow="现场管理" title="施工人员" description="查看在场状态、班组和安全培训" icon={HardHat}><SearchBox value={query} onChange={setQuery} placeholder="搜索姓名、岗位或班组" /><div className="mt-3 grid grid-cols-3 gap-2"><Metric label="人员总数" value={data.length} /><Metric label="当前在场" value={data.filter((i: any) => i.status === "on-site").length} tone="text-emerald-600" /><Metric label="培训异常" value={data.filter((i: any) => !i.safetyTrained).length} tone="text-rose-600" /></div><div className="mt-4 space-y-3">{visible.map((item: any) => <article key={item.id} className="flex items-center gap-3 rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-indigo-100 text-base font-bold text-indigo-600">{item.name.substring(0, 1)}</span><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><h3 className="text-sm font-bold text-slate-900">{item.name}</h3>{!item.safetyTrained && <span className="flex items-center gap-1 rounded-lg bg-rose-50 px-2 py-1 text-[9px] font-bold text-rose-600"><ShieldAlert className="h-3 w-3" />未培训</span>}</div><p className="mt-1 text-xs text-slate-500">{item.role} · {item.team || "未分配"}</p><p className="mt-1 truncate text-[10px] text-slate-400">{item.projects?.find((p: any) => p.status === "active")?.name || "暂无在建项目"}</p></div><div className="flex shrink-0 items-center gap-2"><span className={cn("h-2.5 w-2.5 rounded-full", item.status === "on-site" ? "bg-emerald-500" : "bg-slate-300")} /><button onClick={() => setDeleteId(item.id)} className="rounded-xl bg-rose-50 p-2 text-rose-600"><Trash2 className="h-4 w-4" /></button></div></article>)}</div>{deleteId && <div className="fixed inset-0 z-[90] flex items-center justify-center bg-slate-950/50 p-4"><div className="w-full max-w-sm rounded-3xl bg-white p-5 shadow-xl"><div className="flex items-center gap-3"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-rose-50 text-rose-600"><AlertTriangle className="h-5 w-5" /></span><div><h3 className="text-base font-bold text-slate-900">确认删除</h3><p className="mt-1 text-xs text-slate-500">确定要删除{deleteTarget ? `“${deleteTarget.name}”` : "该人员"}吗？</p></div></div><div className="mt-5 grid grid-cols-2 gap-3"><button onClick={() => setDeleteId(null)} className="rounded-2xl border border-slate-200 py-3 text-sm font-bold text-slate-600">取消</button><button onClick={confirmDelete} className="rounded-2xl bg-rose-600 py-3 text-sm font-bold text-white">确认删除</button></div></div></div>}</Page>;
}

const partnerSeed = [{ id: "EP-001", name: "华东新能源设计院", type: "设计单位", contact: "周工", phone: "13800010001", projectNames: ["C区绿色建筑改造"], scope: "初步设计、深化设计、竣工图", contractId: "C-2025-105", status: "active", requiredDocs: ["营业执照", "资质证书", "施工图交付清单"], uploadedDocs: ["营业执照", "资质证书"] }, { id: "EP-002", name: "安达光伏安装劳务队", type: "劳务队", contact: "刘队", phone: "13800010002", projectNames: ["智能微电网二期"], scope: "支架安装、组件安装", contractId: "", status: "pending-contract", requiredDocs: ["营业执照", "安全协议", "人员证件"], uploadedDocs: ["营业执照"] }];
function MobilePartners() { const [data] = useSyncedAppData<any[]>("externalPartners", []); const [query, setQuery] = useState(""); const visible = data.filter((i: any) => `${i.name}${i.type}${i.contact}`.toLowerCase().includes(query.toLowerCase())); const risky = data.filter((i: any) => !i.contractId || (i.requiredDocs || []).some((doc: string) => !(i.uploadedDocs || []).includes(doc))).length; return <Page eyebrow="外部协作" title="参建外协" description="查看合作单位、合同和资料完整性" icon={Building2}><SearchBox value={query} onChange={setQuery} placeholder="搜索单位、类型或联系人" /><div className="mt-3 grid grid-cols-2 gap-3"><Metric label="合作单位" value={data.length} /><Metric label="风险单位" value={risky} tone="text-rose-600" /></div><div className="mt-4 space-y-3">{visible.map((item: any) => { const missing = (item.requiredDocs || []).filter((doc: string) => !(item.uploadedDocs || []).includes(doc)); return <article key={item.id} className="rounded-3xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><span className="rounded-lg bg-indigo-50 px-2 py-1 text-[10px] font-bold text-indigo-600">{item.type}</span><h3 className="mt-2 truncate text-sm font-bold text-slate-900">{item.name}</h3><p className="mt-1 text-xs text-slate-500">{item.contact} · {item.phone}</p></div>{(!item.contractId || missing.length > 0) && <AlertTriangle className="h-5 w-5 shrink-0 text-rose-500" />}</div><p className="mt-3 rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-600">{item.scope}</p><div className="mt-3 flex flex-wrap gap-2">{!item.contractId && <span className="rounded-lg bg-rose-50 px-2 py-1 text-[10px] font-bold text-rose-600">缺少合同</span>}{missing.map((doc: string) => <span key={doc} className="rounded-lg bg-amber-50 px-2 py-1 text-[10px] font-medium text-amber-600">待补 {doc}</span>)}</div></article>; })}</div></Page>; }

type MobileOrgNode = { id: string; name: string; type?: "company" | "department" | "team"; children?: MobileOrgNode[] };
type MobileOrgDialog = { mode: "add"; parent: MobileOrgNode; name: string } | { mode: "edit"; node: MobileOrgNode; name: string };
const orgSeed: MobileOrgNode = { id: "org-1", name: "智建建筑工程有限公司", type: "company", children: [{ id: "dept-1", name: "工程部", type: "department", children: [{ id: "team-1", name: "土建组", type: "team", children: [] }, { id: "team-2", name: "电气一班", type: "team", children: [] }, { id: "team-3", name: "安装二班", type: "team", children: [] }] }, { id: "dept-2", name: "管理层", type: "department", children: [{ id: "team-5", name: "管理组", type: "team", children: [] }] }, { id: "dept-3", name: "安监部", type: "department", children: [] }, { id: "dept-4", name: "采购部", type: "department", children: [] }] };
function mobileOrgType(node: MobileOrgNode) { return node.type || (node.id.startsWith("org") ? "company" : node.children?.length ? "department" : "team"); }
function mobileChildType(node: MobileOrgNode) { return mobileOrgType(node) === "company" ? "department" : "team"; }
function mobileOrgLabel(type: string) { return type === "company" ? "公司" : type === "department" ? "部门" : "班组"; }
function mobileFindOrg(node: MobileOrgNode, id: string): MobileOrgNode | null { if (node.id === id) return node; for (const child of node.children || []) { const found = mobileFindOrg(child, id); if (found) return found; } return null; }
function mobileOrgNames(node: MobileOrgNode): string[] { return [node.name, ...(node.children || []).flatMap(mobileOrgNames)]; }
function mobileAddOrg(node: MobileOrgNode, parentId: string, child: MobileOrgNode): MobileOrgNode { if (node.id === parentId) return { ...node, children: [...(node.children || []), child] }; return { ...node, children: (node.children || []).map(item => mobileAddOrg(item, parentId, child)) }; }
function mobileRenameOrg(node: MobileOrgNode, nodeId: string, name: string): MobileOrgNode { if (node.id === nodeId) return { ...node, name }; return { ...node, children: (node.children || []).map(item => mobileRenameOrg(item, nodeId, name)) }; }
function mobileRemoveOrg(node: MobileOrgNode, nodeId: string): MobileOrgNode { return { ...node, children: (node.children || []).filter(item => item.id !== nodeId).map(item => mobileRemoveOrg(item, nodeId)) }; }
function MobileOrganization() {
  const [org, setOrg] = useSyncedAppData<MobileOrgNode>("organizationData", createEmptyOrganization());
  const [people, setPeople] = useSyncedAppData<any[]>("personnelData", []);
  const [selectedId, setSelectedId] = useState(org.id);
  const [dialog, setDialog] = useState<MobileOrgDialog | null>(null);
  const selected = mobileFindOrg(org, selectedId) || org;
  const selectedNames = mobileOrgNames(selected);
  const members = people.filter((person: any) => selectedNames.includes(person.team));
  const saveDialog = (event: FormEvent) => {
    event.preventDefault();
    if (!dialog) return;
    const name = dialog.name.trim();
    if (!name) {
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "请填写组织名称" }));
      return;
    }
    if (dialog.mode === "add") {
      const type = mobileChildType(dialog.parent) as MobileOrgNode["type"];
      const child = { id: `${type}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, name, type, children: [] };
      void setOrg(current => mobileAddOrg(current, dialog.parent.id, child));
      setSelectedId(child.id);
      window.dispatchEvent(new CustomEvent("show-toast", { detail: `${mobileOrgLabel(type)}已新增` }));
    } else {
      void setOrg(current => mobileRenameOrg(current, dialog.node.id, name));
      if (dialog.node.name !== name) void setPeople(current => current.map((person: any) => person.team === dialog.node.name ? { ...person, team: name } : person));
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "组织名称已更新" }));
    }
    setDialog(null);
  };
  const deleteNode = (node: MobileOrgNode) => {
    if (mobileOrgType(node) === "company") {
      window.dispatchEvent(new CustomEvent("show-toast", { detail: "公司根节点不能删除" }));
      return;
    }
    const names = mobileOrgNames(node);
    const memberCount = people.filter((person: any) => names.includes(person.team)).length;
    if (!window.confirm(`确定删除“${node.name}”吗？${memberCount ? `相关 ${memberCount} 名成员会变为未分配。` : ""}`)) return;
    void setOrg(current => mobileRemoveOrg(current, node.id));
    void setPeople(current => current.map((person: any) => names.includes(person.team) ? { ...person, team: "" } : person));
    setSelectedId(org.id);
    window.dispatchEvent(new CustomEvent("show-toast", { detail: "组织已删除" }));
  };
  const renderCards = (nodes: MobileOrgNode[], depth = 0) => nodes.map(node => {
    const names = mobileOrgNames(node);
    const count = people.filter((person: any) => names.includes(person.team)).length;
    const active = selected.id === node.id;
    return <div key={node.id} className="space-y-2"><article onClick={() => setSelectedId(node.id)} className={cn("rounded-3xl border bg-white p-4 shadow-sm", active ? "border-indigo-200 ring-2 ring-indigo-100" : "border-slate-100")} style={{ marginLeft: `${Math.min(depth, 2) * 14}px` }}><div className="flex items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><span className={cn("flex h-10 w-10 shrink-0 items-center justify-center rounded-xl", mobileOrgType(node) === "department" ? "bg-amber-50 text-amber-600" : "bg-emerald-50 text-emerald-600")}><Users className="h-5 w-5" /></span><div className="min-w-0"><h3 className="truncate text-sm font-bold text-slate-900">{node.name}</h3><p className="mt-1 text-xs text-slate-400">{mobileOrgLabel(mobileOrgType(node))} · {count} 名成员</p></div></div><ChevronRight className="h-5 w-5 shrink-0 text-slate-300" /></div></article>{node.children?.length ? <div className="space-y-2">{renderCards(node.children, depth + 1)}</div> : null}</div>;
  });
  return <Page eyebrow="企业架构" title="公司组织" description="维护部门、班组和人员分布" icon={FolderTree}><div className="mt-4 rounded-3xl bg-indigo-600 p-4 text-white"><div className="flex items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-white/15"><Building2 className="h-5 w-5" /></span><div className="min-w-0"><h3 className="truncate text-sm font-bold">{selected.name}</h3><p className="mt-1 text-xs text-indigo-200">{mobileOrgLabel(mobileOrgType(selected))} · {members.length} 名成员</p></div></div><div className="flex shrink-0 gap-1"><button onClick={() => setDialog({ mode: "add", parent: selected, name: "" })} className="rounded-xl bg-white/15 p-2"><Plus className="h-4 w-4" /></button><button onClick={() => setDialog({ mode: "edit", node: selected, name: selected.name })} className="rounded-xl bg-white/15 p-2"><Edit2 className="h-4 w-4" /></button><button onClick={() => deleteNode(selected)} className="rounded-xl bg-white/15 p-2"><Trash2 className="h-4 w-4" /></button></div></div></div><div className="mt-4 space-y-3">{renderCards(org.children || [])}</div>{dialog && <div className="fixed inset-0 z-[80] flex items-end bg-slate-950/50"><form onSubmit={saveDialog} className="w-full rounded-t-[32px] bg-white p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="text-lg font-bold text-slate-900">{dialog.mode === "add" ? `新增${mobileOrgLabel(mobileChildType(dialog.parent))}` : "重命名组织"}</h3><p className="mt-1 text-xs text-slate-500">{dialog.mode === "add" ? `上级：${dialog.parent.name}` : `当前：${dialog.node.name}`}</p></div><button type="button" onClick={() => setDialog(null)} className="rounded-full bg-slate-100 p-2 text-slate-500"><X className="h-5 w-5" /></button></div><input autoFocus value={dialog.name} onChange={(event) => setDialog({ ...dialog, name: event.target.value })} className="survey-input" placeholder="请输入组织名称" /><button type="submit" className="mt-4 w-full rounded-2xl bg-indigo-600 py-3.5 text-sm font-bold text-white">保存并同步</button></form></div>}</Page>;
}

const settingsSeed = { notifications: { lowStock: true, delayedTasks: true, urgentAnnouncements: true, emailAlerts: false, pushAlerts: true }, security: { twoFactorAuth: false }, fileManagement: { autoRename: true, autoCreateFolders: true } };
function MobileSettings() { const [settingsData, setSettings] = useSyncedAppData<any>("appSettings", settingsSeed); const settings = { notifications: { ...settingsSeed.notifications, ...(settingsData?.notifications || {}) }, security: { ...settingsSeed.security, ...(settingsData?.security || {}) }, fileManagement: { ...settingsSeed.fileManagement, ...(settingsData?.fileManagement || {}) } }; const toggle = (group: string, key: string) => setSettings((current: any) => ({ ...current, [group]: { ...(current?.[group] || {}), [key]: !settings[group as keyof typeof settings][key as never] } })); const groups = [{ title: "通知提醒", icon: Bell, group: "notifications", items: [["lowStock", "库存预警"], ["delayedTasks", "任务延期"], ["urgentAnnouncements", "紧急公告"], ["pushAlerts", "手机推送"]] }, { title: "安全", icon: ShieldAlert, group: "security", items: [["twoFactorAuth", "双重验证"]] }, { title: "资料管理", icon: FolderOpen, group: "fileManagement", items: [["autoRename", "自动规范命名"], ["autoCreateFolders", "自动创建阶段资料夹"]] }]; return <Page eyebrow="个人与系统" title="设置" description="手机版仅保留常用开关，路径等高级配置请使用桌面端" icon={Settings}><div className="mt-4 space-y-4">{groups.map((section) => { const Icon = section.icon; return <section key={section.title} className="overflow-hidden rounded-3xl border border-slate-100 bg-white shadow-sm"><div className="flex items-center gap-2 border-b border-slate-100 px-4 py-3"><Icon className="h-4 w-4 text-indigo-600" /><h3 className="text-sm font-bold text-slate-900">{section.title}</h3></div><div>{section.items.map(([key, label]) => { const checked = Boolean((settings as any)[section.group][key]); return <button key={key} onClick={() => void toggle(section.group, key)} className="flex w-full items-center justify-between border-b border-slate-50 px-4 py-3.5 text-left last:border-0"><span className="text-sm text-slate-700">{label}</span><span className={cn("relative h-7 w-12 rounded-full transition-colors", checked ? "bg-indigo-600" : "bg-slate-200")}><span className={cn("absolute top-1 h-5 w-5 rounded-full bg-white shadow-sm transition-transform", checked ? "translate-x-6" : "translate-x-1")} /></span></button>; })}</div></section>; })}</div></Page>; }
